% a) Data and design matrix
weeks = [1 2 3 4 5]';
gripStrength = [2.1 3.9 6.2 7.8 10.1]';
A_design = [weeks, ones(size(weeks))];

% b) Solve the normal equation
beta = (A_design'*A_design) \ (A_design'*gripStrength);
disp(beta)

% c) Fitted values, residuals, and R^2
gripFit = A_design*beta;
r = gripStrength - gripFit;
R2 = 1 - (r'*r) / ((gripStrength-mean(gripStrength))'*(gripStrength-mean(gripStrength)));
