% a) Data and design matrix
HR = [62 68 74 70 78 65 72 80]';
BMI = [22 24 27 25 29 23 26 30]';
RecoveryScore = [47.7 52.6 59.9 54.6 63.9 50.3 56.9 66.4]';
A_design = [HR, BMI, ones(size(HR))];

% b) Solve the normal equation
beta = (A_design'*A_design) \ (A_design'*RecoveryScore);
disp(beta)

% c) Fitted values, residuals, R^2
fitted = A_design*beta;
r = RecoveryScore - fitted;
R2 = 1 - (r'*r) / ((RecoveryScore-mean(RecoveryScore))'*(RecoveryScore-mean(RecoveryScore)));
disp(R2)

% d) Residual for subject 4
disp(r(4))

% e) Predict a new subject's score
newPrediction = [75 28 1] * beta;
