% a) Drug 1: well-conditioned system
A_good = [2 1; 1 3];
b1 = [5; 8];
x1 = A_good\b1;
cond_good = cond(A_good);

% b) Drug 2: nearly-singular system
A_bad = [1 1; 1 1.0005];
b2 = [2; 2.0005];
x2 = A_bad\b2;
cond_bad = cond(A_bad);

% c) Perturb both systems by the same small amount and re-solve
b1_pert = b1 + [0.01; -0.01];
x1_pert = A_good\b1_pert;
change_good = norm(x1_pert - x1);

b2_pert = b2 + [0.01; -0.01];
x2_pert = A_bad\b2_pert;
change_bad = norm(x2_pert - x2);

disp([cond_good, cond_bad])
disp([change_good, change_bad])

% d) Written comparison:
% Drug 1's condition number is small (about 2.6), and the same tiny perturbation to b
% only moved its solution by about 0.01 -- proportional to the size of the perturbation
% itself. Drug 2's condition number is enormous (about 8000), and the identical-sized
% perturbation moved its solution by more than 56 units -- wildly out of proportion to
% how small the input change was. Because real plasma-concentration measurements always
% carry at least some noise, Drug 2's fitted transfer-rate coefficients cannot be trusted:
% almost any two runs of the same experiment would produce drastically different
% "best-fit" coefficients, even though the underlying biology hasn't changed.

% a) Simulated readings and calibration coefficients
rawVoltage = linspace(0, 5, 2000000);
a = 0.8; b = 1.2; c = 0.05;

% b) Loop-based transform (preallocated)
concLoop = zeros(size(rawVoltage));
tic
for i = 1:length(rawVoltage)
    concLoop(i) = a*rawVoltage(i)^2 + b*rawVoltage(i) + c;
end
t_loop = toc;

% c) Vectorized transform
tic
concVec = a*rawVoltage.^2 + b*rawVoltage + c;
t_vec = toc;

% d) Confirm agreement and report timing
maxDiff = max(abs(concLoop - concVec));
fprintf('Loop: %.4f sec, Vectorized: %.4f sec, Max difference: %.2e\n', t_loop, t_vec, maxDiff);

% a) Data
day = (0:8)';
mobilityScore = [2.1 4.55 7.15 8.65 10.05 10.95 10.85 10.85 9.95]';

% b) Linear fit
A_lin = [day, ones(size(day))];
beta_lin = (A_lin'*A_lin) \ (A_lin'*mobilityScore);
fit_lin = A_lin*beta_lin;
r_lin = mobilityScore - fit_lin;
R2_lin = 1 - (r_lin'*r_lin) / ((mobilityScore-mean(mobilityScore))'*(mobilityScore-mean(mobilityScore)));
disp(R2_lin)

% c) Quadratic fit
A_quad = [day.^2, day, ones(size(day))];
beta_quad = (A_quad'*A_quad) \ (A_quad'*mobilityScore);
fit_quad = A_quad*beta_quad;
r_quad = mobilityScore - fit_quad;
R2_quad = 1 - (r_quad'*r_quad) / ((mobilityScore-mean(mobilityScore))'*(mobilityScore-mean(mobilityScore)));
disp(R2_quad)

% d) Compare against polyfit
p = polyfit(day, mobilityScore, 2);
maxCoeffDiff = max(abs(beta_quad' - p));
disp(maxCoeffDiff)

% e) Written explanation:
% R2 jumps from about 0.75 for the linear model to about 0.998 for the quadratic model,
% which means a straight line misses a real, systematic curvature in the data -- mobility
% doesn't just rise at a constant rate, it rises quickly at first and then levels off and
% even dips slightly, which only a model with a day^2 term can capture.

% a) Simulated readings
glucose = 70 + 60*rand(1,50000);
threshold = 125;

% b) Growing array (no preallocation)
tic
flagsGrow = [];
for i = 1:length(glucose)
    if glucose(i) > threshold
        flagsGrow(end+1) = 1;
    else
        flagsGrow(end+1) = 0;
    end
end
t_grow = toc;

% c) Preallocated loop
tic
flagsPre = zeros(1, length(glucose));
for i = 1:length(glucose)
    if glucose(i) > threshold
        flagsPre(i) = 1;
    else
        flagsPre(i) = 0;
    end
end
t_pre = toc;

% d) Vectorized, no loop
tic
flagsVec = double(glucose > threshold);
t_vec = toc;

% e) Confirm agreement and report timing
allMatch = isequal(flagsGrow, flagsPre) && isequal(flagsPre, flagsVec);
fprintf('Match: %d | Grow: %.4f sec, Prealloc: %.4f sec, Vectorized: %.4f sec\n', allMatch, t_grow, t_pre, t_vec);
fprintf('Readings flagged: %d\n', sum(flagsVec));

% a) Build the system and check rank/determinant
A = [1 2 1; 2 4.001 2; 1 1 3];
b = [8; 16.002; 9];
A_rank = rank(A);
detA = det(A);
disp(A_rank)
disp(detA)

% b) Solve
x = A\b;
disp(x)

% c) Condition number
condA = cond(A);
disp(condA)

% d) Perturb the second measurement slightly and re-solve
b_pert = b + [0; 0.01; 0];
x_pert = A\b_pert;
change = norm(x_pert - x);
disp(change)

% e) Written reconciliation:
% rank(A) reports 3 -- technically "full rank," which is the textbook condition for a
% unique solution to exist -- yet cond(A) is roughly 37,000, an enormous number, because
% the first two rows of A are nearly duplicates of each other (row 2 is almost exactly
% 2 times row 1). rank is a binary, all-or-nothing test: it only asks whether A is
% invertible at all, not how close it is to failing to be invertible. A tiny, entirely
% realistic 0.01 measurement error on just one experiment shifted the fitted rate
% constants by more than 27 units in norm -- larger than the solution itself -- which
% shows that "full rank" alone provides no protection against this kind of instability.
% Any credible parameter-identification workflow needs to check cond(A), not just
% rank(A), before trusting the fitted values.

% a) Data and design matrix
Age = [65 70 58 72 61]';
BMI = [24 27 21 29 23]';
SBP = [120 128 115 132 118]';
Chol = [190 205 180 210 188]';
RiskScore = [45 62 30 68 38]';
A_design = [Age, BMI, SBP, Chol, ones(5,1)];

% b) Solve (square system -- backslash directly)
beta = A_design\RiskScore;
disp(beta)

% c) Fit quality
fitted = A_design*beta;
r = RiskScore - fitted;
R2 = 1 - (r'*r) / ((RiskScore-mean(RiskScore))'*(RiskScore-mean(RiskScore)));
disp(R2)

% d) Rank and condition number
disp(rank(A_design))
disp(cond(A_design))

% e) Written explanation:
% R2 comes out to essentially 1.0 because A_design is a square, invertible 5x5 matrix
% solving for exactly 5 parameters from exactly 5 data points -- with that many free
% parameters, the model has enough flexibility to pass exactly through every single
% observation, regardless of whether Age, BMI, SBP, and Cholesterol actually have any
% real relationship to RiskScore at all. A "perfect" fit here is a guaranteed mathematical
% consequence of having as many parameters as data points (an exactly-determined system),
% not evidence of a good or generalizable model -- this is the same overfitting trap
% described in lecture with the 20-protein wing-size example. To actually trust a model
% like this, you would need substantially more subjects than predictors (an over-determined
% system), so that the least-squares fit has to compromise across many observations rather
% than simply reproducing each one exactly.

% a) Simulated image and threshold
img = rand(800, 800);
threshold = 0.6;

% b) Naive nested loop
tic
for i = 1:800
    for j = 1:800
        if img(i,j) > threshold
            mask1(i,j) = 1;
        else
            mask1(i,j) = 0;
        end
    end
end
t_loop = toc;

% c) Preallocated + vectorized logical indexing
tic
mask2 = zeros(800,800);
mask2(img > threshold) = 1;
t_vec = toc;

% d) Confirm agreement and report timing
disp(isequal(mask1, mask2))
fprintf('Loop: %.4f sec, Vectorized: %.4f sec\n', t_loop, t_vec);
fprintf('Pixels flagged: %d\n', sum(mask2(:)));

% e) Written explanation:
% Running the Profiler on the naive version would almost certainly flag the
% "mask1(i,j) = 1;" / "mask1(i,j) = 0;" assignment inside the nested loop as the single
% most time-consuming line, because it executes 640,000 times (800 rows x 800 columns),
% and since mask1 is never preallocated, many of those assignments also force MATLAB to
% grow the array. The one-time img = rand(800,800) line, by contrast, executes exactly
% once and is handled by a single optimized built-in call, so no matter how "large" that
% line looks, it cannot compete with a line that runs 640,000 separate times.

% a) Data
dose = (0:2:16)';
viability = [95.3 93.0 90.8 86.3 81.9 74.8 67.5 58.3 49.0]';

% b) Linear fit
A_lin = [dose, ones(size(dose))];
beta_lin = (A_lin'*A_lin) \ (A_lin'*viability);
fit_lin = A_lin*beta_lin;
r_lin = viability - fit_lin;
R2_lin = 1 - (r_lin'*r_lin) / ((viability-mean(viability))'*(viability-mean(viability)));
disp(R2_lin)
disp(r_lin')

% c) Written observation:
% r_lin's signs run negative, negative, positive, positive, positive, positive, positive,
% negative, negative -- a clear hump shape, not a random back-and-forth pattern. This kind
% of systematic residual pattern indicates the straight line is missing real curvature in
% the data, regardless of how large R2_lin itself looks.

% d) Quadratic fit
A_quad = [dose.^2, dose, ones(size(dose))];
beta_quad = (A_quad'*A_quad) \ (A_quad'*viability);
fit_quad = A_quad*beta_quad;
r_quad = viability - fit_quad;
R2_quad = 1 - (r_quad'*r_quad) / ((viability-mean(viability))'*(viability-mean(viability)));
fprintf('R2 linear: %.4f, R2 quadratic: %.4f\n', R2_lin, R2_quad);

% e) Extrapolate to dose = 30 Gy
extrapolated = beta_quad(1)*30^2 + beta_quad(2)*30 + beta_quad(3);
disp(extrapolated)

% f) Written explanation:
% extrapolated comes out negative (around -53.5% viability), which is physically
% impossible -- a percentage can never go below 0%. This happens because the quadratic
% term that fits the observed 0-16 Gy range so well (R2 ~ 0.9996) curves downward
% increasingly steeply once you plug in a dose far outside that range, and nothing in the
% fitting process "knows" that viability must stay within [0, 100]. A high R2 only
% certifies that a model describes the data it was fit on; it says nothing about the
% model's behavior outside that range, which is why extrapolating a polynomial fit --
% however good it looks in-sample -- is a common and dangerous mistake.
